const SKIP = new Set(['when', 'unless', 'id', 'chapters', 'meaningTags', 'calculationSources', 'sourceRuleIds', 'conflicts', 'version', 'system', 'status', 'confidence', 'priority', 'evidenceKind', 'storyKey']);
function fixStr(s, used) { let v = s; FIX.forEach(([a, b, all], i) => { if (v.includes(a)) { used[i] = (used[i] || 0) + 1; v = all ? v.split(a).join(b) : v.replace(a, b); } }); return v; }
function walk(o, used) { if (typeof o === 'string') return fixStr(o, used); if (Array.isArray(o)) return o.map(x => walk(x, used)); if (o && typeof o === 'object') { const out = {}; for (const k of Object.keys(o)) out[k] = SKIP.has(k) ? o[k] : walk(o[k], used); return out; } return o; }
const USED = {};
export function applyConsistency(list) { return list.map(e => walk(e, USED)); }
// 모든 묶음에 적용한 뒤 부른다: 한 번도 쓰이지 않은 줄이 있으면 원문이 바뀐 것이니 멈춘다
export function checkConsistencyUsed() { const miss = FIX.map((f, i) => USED[i] ? null : f[0]).filter(Boolean); if (miss.length) throw new Error('consistency-20261124: 원문을 찾지 못한 줄 ' + miss.length + '개 — ' + miss.slice(0, 3).join(' | ')); }
export const CONSISTENCY_FIX = FIX;
